// Adapter: gate-check  (Approval, lane: The gate)
//
// A person pressed approve or reject on the form. This decides whether that press counts: the
// row has to exist, be ready for approval, and not be approved already. Pressing twice is
// harmless; the second press learns who pressed first.
//
// Node settings: JavaScript, Run Once for All Items.

const settings = $('Configuration (gate)').first().json;
const form = $('Approval form').first().json;
const now = new Date().toISOString();

const ref = String(form.shipment_ref || '').trim();
const decision = String(form.decision || '').trim().toLowerCase();
const name = String(form.your_name || '').trim();
const comment = String(form.comment || '').trim();

// The read arrives either as one item per row, or as one item carrying the whole page under
// `value` (the HTTP read). Flatten both, take the columns off `fields`, pick the row here.
const flatten = (items) => items.flatMap((i) => (i.json && Array.isArray(i.json.value) ? i.json.value : [i.json]));
const found = flatten($('Read the shipment row').all())
  .filter((r) => r && r.id)
  .map((r) => Object.assign({ _id: r.id }, r.fields || r))
  .filter((r) => String(r.Title || '').trim() === ref);
const row = found[0] || null;

const refuse = (reason) => [{ json: { ok: false, reason, shipment_ref: ref } }];

if (ref === '') return refuse('No shipment reference was given');
if (!row) return refuse(`No shipment ${ref} on the Shipments list`);
if (String(row.approved_at || '').trim() !== '') {
  return refuse(`${ref} was already approved by ${row.approved_by || 'somebody'} on ${String(row.approved_at).slice(0, 10)}`);
}
if (String(row.status || '') !== SD_ENGINE.STATUS.ready) {
  return refuse(`${ref} is not ready for approval. Its status is "${row.status || 'unset'}" and its next step is: ${row.next_step || 'unset'}`);
}
if (name === '') return refuse('Give your name. The approval is recorded against it');
if (decision !== 'approve' && decision !== 'reject') return refuse('Choose approve or reject');

if (decision === 'reject') {
  return [{
    json: {
      ok: true,
      decision,
      shipment_ref: ref,
      row_id: row._id,
      row_update: {
        Title: ref,
        status: 'drafts rejected',
        next_step: `rejected by ${name}${comment ? ': ' + comment : ''}`,
      },
      log: { Title: ref, event: 'rejected', detail: comment || 'no comment', actor: name, at: now },
      notice: null,
      message: `${ref} rejected. The row says so and names you. Nothing was sent to the counterparty; tell them yourself, with the reason.`,
    },
  }];
}

const originals = SD_ENGINE.requirementsFor(row.contract_ref, flatten($('Read the document requirements (gate)').all()).map((r) => r.fields || r))
  .filter((r) => r.required && r.original_required)
  .map((r) => r.label);

const to = String(row.counterparty_email || '').trim();
const notice = originals.length === 0 || to === '' ? null : {
  to,
  cc: '',
  subject: `${ref}: drafts approved, please send the original ${originals.join(', ')}`,
  body: [
    `The draft documents for shipment ${ref} (${row.commodity || 'goods'}, ${row.vessel || 'vessel'} to ${row.port_of_discharge || 'destination'}) have been approved.`,
    '',
    `Please courier the original ${originals.join(', ')} and reply with the airway bill number.`,
    '',
    settings.disclaimer,
  ].join('\n'),
};

return [{
  json: {
    ok: true,
    decision,
    shipment_ref: ref,
    row_id: row._id,
    row_update: {
      Title: ref,
      status: originals.length === 0 ? 'complete' : 'awaiting originals',
      next_step: originals.length === 0
        ? 'ready to present'
        : (notice ? `originals requested, awaiting original ${originals.join(', ')}` : `awaiting original ${originals.join(', ')} - no counterparty email on the row, request them yourself`),
      approved_by: name,
      approved_at: now,
      chase_count: 0,
      last_chased: null,
    },
    log: { Title: ref, event: 'approved', detail: comment || 'no comment', actor: name, at: now },
    notice,
    message: notice
      ? `${ref} approved. A request for the original ${originals.join(', ')} has gone to ${to}. The daily scan will chase from day ${settings.chase_after_days}.`
      : `${ref} approved.${originals.length === 0 ? ' No originals are required for this contract.' : ' There is no counterparty email on the row, so nobody was asked for the originals.'}`,
  },
}];
